with metrics as (select *, lag(age) over (partition by city order by credit_limit, id) as prev_age, lead(credit_limit) over (partition by city order by credit_limit, id) as next_credit_limit, lag(credit_limit) over (partition by city order by credit_limit, id) as prev_credit_limit, row_number() over (partition by city order by credit_limit, id) as event_seq from customers) select id, city, signup_date, is_active, credit_limit, prev_age, next_credit_limit, case when city rlike '^(New York|Bangkok)$' then 'OTHER_ZONE' else 'PRIORITY' end as city_zone from metrics order by city_zone nulls last;
